+
+            // Emphasize Given/When/Then keywords
+            const emphasized = content
+                .replace(/\*?\*?(Given)\*?\*?/gi, '<strong class="keyword-given">$1</strong>')
+                .replace(/\*?\*?(When)\*?\*?/gi, '<strong class="keyword-when">$1</strong>')
