+
+    // Store original content for cancel
+    const originalHtml = contentEl.innerHTML;
+
+    // Create input
+    const input = document.createElement('input');
+    input.type = 'text';
+    input.value = content.trim();
+    input.className = 'inline-edit-input';
+
+    // Handle keyboard events
