+/**
+ * SpecKit Companion - Base Styles
+ * Reset, body, and layout styles
+ */
+
+/* ============================================
+   Base Styles
+   ============================================ */
+
+* {
+    box-sizing: border-box;
+    margin: 0;
+    padding: 0;
+}
+
+body {
+    font-family: var(--font-family);
+    font-size: var(--font-size);
+    background: var(--bg-primary);
+    color: var(--text-primary);
+    line-height: 1.6;
+    -webkit-font-smoothing: antialiased;
+    -moz-osx-font-smoothing: grayscale;
+}
+
+/* ============================================
+   Layout Container
+   ============================================ */
+
+.viewer-container {
+    display: flex;
+    flex-direction: column;
+    height: 100vh;
+    overflow: hidden;
+}
+
+/* Instant render - no animation delay */
+.viewer-container {
+    opacity: 1;
+}
+
+/* ============================================
+   Content Area
+   ============================================ */
+
+.content-area {
+    flex: 1;
+    overflow-y: auto;
+    padding: var(--content-padding);
+    scroll-behavior: smooth;
+}
+
+/* ============================================
+   Empty State
+   ============================================ */
+
+.empty-state {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    min-height: 200px;
+    color: var(--text-secondary);
+    font-style: italic;
+    text-align: center;
+    padding: var(--content-padding);
+}
+
+/* ============================================
+   Scrollbar Styling
+   ============================================ */
+
+.content-area::-webkit-scrollbar {
+    width: 10px;
+}
+
+.content-area::-webkit-scrollbar-track {
+    background: transparent;
+}
+
+.content-area::-webkit-scrollbar-thumb {
+    background: var(--border);
+    border-radius: 5px;
+}
+
+.content-area::-webkit-scrollbar-thumb:hover {
+    background: var(--border-hover);
+}
+
+/* ============================================
+   Focus States (Accessibility)
+   ============================================ */
+
+button:focus-visible,
+a:focus-visible,
+input:focus-visible {
+    outline: 2px solid var(--accent);
+    outline-offset: 2px;
+}
+
+/* ============================================
+   High Contrast Theme Adjustments
+   ============================================ */
+
+@media (prefers-contrast: more) {
+    .tab-button.active {
+        outline: 2px solid var(--accent);
+        outline-offset: -2px;
+    }
+
+    .edit-button:focus {
+        outline: 2px solid var(--accent);
+        outline-offset: 2px;
+    }
+
+    #markdown-content a {
+        text-decoration: underline;
+    }
+
+    .step-indicator {
+        border-width: 3px;
+    }
+}
+
+/* ============================================
+   Responsive Adjustments
+   ============================================ */
+
+@media (max-width: 500px) {
+    .actions {
+        padding: 8px 12px;
+    }
+
+    .actions button {
+        padding: 6px 10px;
+        font-size: 12px;
+    }
+
+    .actions-right .secondary {
+        display: none;
+    }
+
+    .phase-stepper {
+        padding: 12px 16px;
+    }
+
+    .step-connector {
+        width: 30px;
+    }
+
+    .step-indicator {
+        width: 30px;
+        height: 30px;
+        font-size: 12px;
+    }
+}

