+/**
+ * SpecKit Companion - Content Styles
+ * Markdown rendering base styles
+ */
+
+/* ============================================
+   Markdown Content Styles
+   ============================================ */
+
+#markdown-content {
+    font-family: var(--font-family);
+    font-size: 14px;
