+    text-decoration: underline;
+    color: var(--accent-hover);
+}
+
+/* ============================================
+   Horizontal rules
+   ============================================ */
+
+#markdown-content hr {
+    margin: 16px 0;
+    border: none;
+    border-top: 1px solid var(--border);
+}
+
+/* ============================================
+   Images
+   ============================================ */
+
+#markdown-content img {
