+    /** Related documents */
+    relatedDocs: SpecDocument[];
+    /** Currently displayed document type */
+    currentDoc: DocumentType;
+    /** Current workflow phase */
+    workflowPhase: 'spec' | 'plan' | 'tasks' | 'done';
