+    let html = '';
+    const lines = markdown.split('\n');
+    let inCodeBlock = false;
+    let codeBlockLang = '';
+    let codeContent: string[] = [];
+    let inList = false;
+    let listType: 'ul' | 'ol' = 'ul';
+    let inTable = false;
+    let tableRows: string[] = [];
+
+    for (let i = 0; i < lines.length; i++) {
