-        { regex: /^>\s*\[!WARNING\]\s*\n((?:>.*\n?)*)/gim, type: 'warning', label: 'Warning' },
-        { regex: /^>\s*\[!IMPORTANT\]\s*\n((?:>.*\n?)*)/gim, type: 'important', label: 'Important' },
