+/**
+ * SpecKit Companion - Animation Styles
+ * Keyframes and animations
+ */
+
+/* ============================================
+   Keyframe Animations
+   ============================================ */
+
+@keyframes spin {
+    to {
+        transform: rotate(360deg);
+    }
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; }
+    to { opacity: 1; }
+}
+
+@keyframes slideDown {
+    from {
+        opacity: 0;
+        transform: translateY(-8px);
+    }
+    to {
+        opacity: 1;
+        transform: translateY(0);
+    }
+}
+
+@keyframes slideIn {
+    from {
+        opacity: 0;
+        transform: translateX(10px);
+    }
+    to {
+        opacity: 1;
+        transform: translateX(0);
+    }
+}
+
+@keyframes modalSlideIn {
+    from {
+        opacity: 0;
+        transform: translate(-50%, -48%);
+    }
+    to {
+        opacity: 1;
+        transform: translate(-50%, -50%);
+    }
+}
+
+/* Pulsing blue glow for active tasks progress badge */
+@keyframes pulse-badge {
+    0%, 100% {
+        box-shadow: 0 0 0 3px var(--accent-subtle), 0 0 8px var(--accent);
+    }
+    50% {
+        box-shadow: 0 0 0 5px var(--accent-subtle), 0 0 16px var(--accent);
+    }
+}
+
+/* Glowing green effect for PROJECT COMPLETE badge */
+@keyframes glow-complete {
+    0%, 100% {
+        box-shadow: 0 0 8px color-mix(in srgb, var(--success) 40%, transparent);
+        border-color: var(--success);
+    }
+    50% {
+        box-shadow: 0 0 16px color-mix(in srgb, var(--success) 60%, transparent);
+        border-color: color-mix(in srgb, var(--success) 80%, white);
+    }
+}
+
+/* Purple glow for review mode */
+@keyframes review-glow {
+    0%, 100% {
+        box-shadow: 0 0 0 0 transparent;
+    }
+    50% {
+        box-shadow: 0 0 8px var(--review-glow);
+    }
+}

