+/**
+ * SpecKit Companion - Code Block Styles
+ * Code blocks, syntax highlighting, and mermaid diagrams
+ */
+
+/* ============================================
+   Code Blocks
+   ============================================ */
+
+/* Code block container - professional style */
+#markdown-content pre.code-block {
+    position: relative;
+    margin: var(--space-5) 0;
+    padding: 0;
+    background: var(--bg-code);
+    border: 1px solid var(--border-code);
+    border-radius: var(--radius-lg);
+    overflow: hidden;
+}
+
+/* Language label */
+#markdown-content pre.code-block::before {
+    content: attr(data-language);
+    display: block;
+    padding: var(--space-2) var(--space-4);
+    font-size: var(--text-xs);
+    font-weight: 600;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    color: var(--text-muted);
+    background: var(--bg-code-header);
+    border-bottom: 1px solid var(--border-code);
+}
+
+#markdown-content pre.code-block:not([data-language])::before {
+    display: none;
+}
+
+#markdown-content pre.code-block code {
+    display: block;
+    padding: var(--space-4);
+    font-family: var(--font-mono);
+    font-size: var(--text-sm);
+    line-height: var(--leading-relaxed);
+    overflow-x: auto;
+    tab-size: 4;
+    color: var(--code-text);
+    background: transparent;
+    border: none;
+}
+
+/* Tree structure blocks */
+#markdown-content pre.tree-structure {
+    background: var(--bg-secondary);
+    border: 1px solid var(--border);
+    border-radius: var(--radius-md);
+    padding: var(--space-4);
+    margin: var(--space-4) 0;
+    overflow-x: auto;
+}
+
+#markdown-content pre.tree-structure code {
+    font-family: var(--font-mono);
+    font-size: var(--text-sm);
+    line-height: var(--leading-normal);
+    color: var(--text-secondary);
+    white-space: pre;
+    display: block;
+    background: transparent;
+    border: none;
+    padding: 0;
+}
+
+/* Legacy pre blocks (fallback) */
+#markdown-content pre:not(.code-block):not(.tree-structure):not(.mermaid) {
+    margin: var(--space-4) 0;
+    padding: var(--space-4);
+    background: var(--bg-secondary);
+    border: 1px solid var(--border);
+    border-radius: var(--radius-md);
+    overflow-x: auto;
+}
+
+#markdown-content pre:not(.code-block):not(.tree-structure):not(.mermaid) code {
+    font-family: var(--font-mono);
+    font-size: var(--text-sm);
+    line-height: var(--leading-normal);
+    display: block;
+    color: var(--text-secondary);
+    background: none;
+    border: none;
+    padding: 0;
+}
+
+/* ============================================
+   Syntax Highlighting (hljs compatibility)
+   ============================================ */
+
+/* Only override background to be transparent - let CDN styles handle colors */
+.hljs {
+    background: transparent !important;
+}
+
+/* Ensure code blocks have proper padding when hljs is applied */
+pre.code-block code.hljs {
+    padding: var(--space-4);
+}
+
+/* ============================================
+   Mermaid Diagram Styling
+   ============================================ */
+
+.mermaid-container {
+    margin: var(--space-5) 0;
+    padding: var(--space-4);
+    background: var(--bg-secondary);
+    border: 1px solid var(--border);
+    border-radius: var(--radius-lg);
+    overflow-x: auto;
+}
+
+.mermaid {
+    display: flex;
+    justify-content: center;
+    background: transparent;
+    font-family: var(--font-family);
+}
+
+.mermaid svg {
+    max-width: 100%;
+    height: auto;
+}
+
+/* Mermaid theme overrides for better VS Code integration */
+.mermaid .node rect,
+.mermaid .node circle,
+.mermaid .node ellipse,
+.mermaid .node polygon {
+    fill: var(--bg-elevated) !important;
+    stroke: var(--accent) !important;
+    stroke-width: 2px !important;
+}
+
+.mermaid .node .label,
+.mermaid .nodeLabel,
+.mermaid .label {
+    color: var(--text-primary) !important;
+    fill: var(--text-primary) !important;
+}
+
+.mermaid .edgePath .path {
+    stroke: var(--accent) !important;
+    stroke-width: 2px !important;
+}
+
+.mermaid .edgeLabel {
+    background-color: var(--bg-secondary) !important;
+    color: var(--text-primary) !important;
+    fill: var(--text-primary) !important;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+/* State diagram specific */
+.mermaid .statediagram-state rect {
+    fill: var(--bg-elevated) !important;
+    stroke: var(--accent) !important;
+}
+
+.mermaid .statediagram-state .state-title {
+    fill: var(--text-primary) !important;
+    font-weight: 600;
+}
+
+/* Edge labels (transition labels) */
+.mermaid .transition,
+.mermaid .edgeLabel span,
+.mermaid .edgeLabel p,
+.mermaid text.edgeLabel {
+    fill: var(--header-section) !important;
+    color: var(--header-section) !important;
+    font-weight: 500;
+}
+
+/* Start/end nodes */
+.mermaid .start-state,
+.mermaid circle[class*="start"] {
+    fill: var(--success) !important;
+}
+
+.mermaid .end-state,
+.mermaid circle[class*="end"] {
+    fill: var(--text-muted) !important;
+}

