+    box-shadow: 0 0 0 2px var(--bg-secondary), 0 0 0 3px color-mix(in srgb, var(--success) 60%, transparent);
+}
+
+.step-tab.workflow:not(.viewing) .step-label {
+    color: var(--text-primary);
+}
+
