+    border-color: var(--accent);
+    color: white;
+    font-size: 8px;
+    width: auto;
+    min-width: 24px;
+    padding: 0 4px;
+    border-radius: 8px;
+}
+
+/* Tasks actively being worked on - prominent percentage badge with pulsing glow */
+.step-tab.tasks-active {
+    background: var(--accent-subtle);
+    border: 2px solid var(--accent);
+    margin: -2px;
+}
+
+.step-tab.tasks-active .step-status {
+    background: var(--accent);
+    border-color: var(--accent);
+    color: white;
+    font-size: 11px;
+    font-weight: 700;
+    width: auto;
+    min-width: 32px;
+    padding: 0 6px;
+    border-radius: 10px;
+    box-shadow: 0 0 0 3px var(--accent-subtle);
