+/* Review mode - viewing a completed step that isn't the current workflow phase */
+.step-tab.reviewing {
+    background: var(--review-subtle);
+    border: 2px solid var(--review);
+    margin: -2px;
+    animation: review-glow 2s ease-in-out infinite;
